/**
 * The repo's internal entry to the `blake3_wasm` build, for its tests and benchmarks:
 * the wasm-pack web target in `pkg/`, initialized synchronously from the
 * `.wasm` file beside it. Runs under Node.js, Bun, and Deno, which all support `node:fs`.
 * The published package's entries are generated by `scripts/patch_npm_package.task.ts`.
 *
 * @module
 */

import { readFileSync } from 'node:fs';

import { make_stream_functions } from '../blake3_wasm_core/stream.ts';
import { Blake3Hasher, derive_key, hash, initSync, keyed_hash } from './pkg/blake3_wasm.js';

initSync({ module: readFileSync(new URL('./pkg/blake3_wasm_bg.wasm', import.meta.url)) });

export { Blake3Hasher, derive_key, hash, keyed_hash };
export const { hash_stream, keyed_hash_stream, derive_key_stream } =
	make_stream_functions(Blake3Hasher);
